  INDEX `template_id_idx`(`template_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '正文配置表' ROW_FORMAT = Dynamic;

